/** The pen line is revealed this many seconds ahead of the ink, so it leads the way. */
const PEN_LEAD = 0.12

interface Placed {
    d: string
    x: number
    /** The glyph actually drawn (unknown characters fall back to "?"). */
    ch: string
}

function layout(text: string) {
    const placed: Placed[] = []
    let x = 0
    let left = Infinity
    let top = Infinity
    let right = -Infinity
    let bottom = -Infinity
    const chars = Array.from(text)
    chars.forEach((ch, i) => {
        const key = GLYPHS[ch] ? ch : "?"
        const g = GLYPHS[key]
        const [adv, d, x1, y1, x2, y2] = g
        if (d !== undefined) {
            placed.push({ d, x, ch: key })
            left = Math.min(left, x + (x1 ?? 0))
            right = Math.max(right, x + (x2 ?? adv))
            top = Math.min(top, y1 ?? 0)
            bottom = Math.max(bottom, y2 ?? 0)
        }
        x += adv + (KERN[ch + (chars[i + 1] ?? "")] ?? 0)
    })
    if (!placed.length) return { placed, box: { x: 0, y: -EM * 0.6, w: EM, h: EM * 0.8 } }
    return { placed, box: { x: left, y: top, w: right - left, h: bottom - top } }
}

export default function Signature(props: Partial<SignatureProps> = {}) {
    const { 
        text = "SignTap", 
        size = BASE_SIZE, 
        duration = 3, 
        stagger = 0, 
        delay = 0, 
        outline = true, 
        inset = 32, 
        style 
    } = props
    const ink = props.ink || "#f5f5f4"
    const ground = props.background || "transparent"
    const reduce = useReducedMotion()
    const rootRef = useRef<HTMLDivElement>(null)
    const inView = useInView(rootRef, { once: true, amount: 0.4 })
    const [take, setTake] = useState(0)
    const maskId = `sig-${React.useId().replace(/:/g, "")}`

    const { placed, box } = useMemo(() => layout(text || " "), [text])
    // The pen's route: every stroke of every letter in writing order, with how far along the whole
    // signature it starts, so one speed carries the pen through all of it.
    const plan = useMemo(() => {
        let run = 0
        const strokes = placed.map((g) =>
            (STROKES[g.ch] ?? []).map(([w, len, d]) => {
                const s = { w, len, d, at: run }
                run += len
                return s
            })
        )
        return { strokes, total: Math.max(1, run) }
    }, [placed])
    // Pad the ink box by half the reveal stroke so the mask never clips a stroke end.
    const pad = EM * REVEAL * 0.5
    const vb = `${box.x - pad} ${box.y - pad} ${box.w + pad * 2} ${box.h + pad * 2}`
    // The drawing's box (ink plus that pad) in ems.
    const a = (box.w + pad * 2) / EM
    const b = (box.h + pad * 2) / EM
    // px per em is the least of: Size itself; Size scaled by how far the
    // frame (inside Inset) falls short of fitting it at 96 px; and what the
    // frame's edges allow, so nothing spills out of it. Container units read
    // the frame, so this holds from the first paint with nothing to measure.
    // Each term below is that em times the box's width (or height) in ems.
    const r = size / BASE_SIZE
    const extent = (e: number) =>
        `min(${(e * size).toFixed(3)}px, ` +
        `(100cqw - ${2 * inset}px) * ${((r * e) / a).toFixed(5)}, ` +
        `(100cqh - ${2 * inset}px) * ${((r * e) / b).toFixed(5)}, ` +
        `100cqw * ${(e / a).toFixed(5)}, ` +
        `100cqh * ${(e / b).toFixed(5)})`
    const play = reduce || inView

    const replay = () => !reduce && setTake((t) => t + 1)

    const variants = {
        hidden: { pathLength: 0, opacity: 0 },
        visible: { pathLength: 1, opacity: 1 },
    }
    // Duration is the whole signature, so the pen keeps one speed (ink units a second) from the
    // first stroke to the last; Stagger adds a pause between letters (0 writes it in one flow).
    const speed = plan.total / Math.max(0.05, duration)
    const timing = (letter: number, s: { len: number; at: number }, lead = 0) => {
        if (reduce) return { duration: 0 }
        const start = Math.max(0, delay + s.at / speed + letter * stagger - lead)
        return {
            pathLength: { delay: start, duration: Math.max(0.001, s.len / speed), ease: "linear" as const },
            opacity: { delay: start, duration: 0.001 },
        }
    }
    const region = { x: box.x - pad, y: box.y - pad, width: box.w + pad * 2, height: box.h + pad * 2 }
    // When a letter's last stroke lands, its mask opens fully, so the finished signature is exactly
    // the letterforms at any Size (the 1.5 px pen line stays 1.5 px however small the letters get).
    const done = { hidden: { opacity: 0 }, visible: { opacity: 1 } }
    const letterEnd = (i: number) => {
        const st = plan.strokes[i]
        const last = st[st.length - 1]
        return { len: 0, at: last ? last.at + last.len : 0 }
    }

    return (
        <div
            ref={rootRef}
            role="button"
            tabIndex={0}
            aria-label={`Signature: ${text}. Activate to sign again.`}
            onClick={replay}
            onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault()
                    replay()
                }
            }}
            style={{
                width: "100%",
                height: "100%",
                ...style,
                boxSizing: "border-box",
                containerType: "size",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                background: ground,
                cursor: reduce ? "default" : "pointer",
                outline: "none",
                userSelect: "none",
                WebkitTapHighlightColor: "transparent",
            }}
        >
            {/* The size sits on a plain box: a motion.svg keeps the style it mounted with, so Size
                would only take effect on the next replay. */}
            <div style={{ flex: "none", width: extent(a), height: extent(b) }}>
                <motion.svg
                    key={take}
                    viewBox={vb}
                    preserveAspectRatio="xMidYMid meet"
                    initial={reduce ? "visible" : "hidden"}
                    animate={play ? "visible" : "hidden"}
                    style={{ display: "block", width: "100%", height: "100%", overflow: "visible" }}
                    aria-hidden
                >
                    <defs>
                        {/* One mask per letter, so a letter's reveal never uncovers its neighbour. */}
                        {placed.map((g, i) => (
                            <mask key={i} id={`${maskId}-${i}`} maskUnits="userSpaceOnUse" {...region}>
                                <g transform={`translate(${g.x} 0)`}>
                                    {plan.strokes[i].map((st, j) => (
                                        <motion.path
                                            key={j}
                                            d={st.d}
                                            stroke="white"
                                            strokeWidth={st.w}
                                            fill="none"
                                            strokeLinecap="round"
                                            strokeLinejoin="round"
                                            variants={variants}
                                            transition={timing(i, st)}
                                        />
                                    ))}
                                </g>
                                <motion.rect {...region} fill="white" variants={done} transition={timing(i, letterEnd(i))} />
                            </mask>
                        ))}
                        {outline &&
                            placed.map((g, i) => (
                                <mask key={i} id={`${maskId}-p${i}`} maskUnits="userSpaceOnUse" {...region}>
                                    <g transform={`translate(${g.x} 0)`}>
                                        {plan.strokes[i].map((st, j) => (
                                            <motion.path
                                                key={j}
                                                d={st.d}
                                                stroke="white"
                                                // a little wider than the ink's, so the outline's outer half shows too
                                                strokeWidth={st.w + 8}
                                                fill="none"
                                                strokeLinecap="round"
                                                strokeLinejoin="round"
                                                variants={variants}
                                                transition={timing(i, st, PEN_LEAD)}
                                            />
                                        ))}
                                    </g>
                                    <motion.rect {...region} fill="white" variants={done} transition={timing(i, letterEnd(i), PEN_LEAD)} />
                                </mask>
                            ))}
                    </defs>
                    {outline &&
                        placed.map((g, i) => (
                            <path
                                key={i}
                                d={`M${g.x} 0${g.d}`}
                                stroke={ink}
                                strokeWidth={1.5}
                                fill="none"
                                vectorEffect="non-scaling-stroke"
                                strokeLinejoin="round"
                                mask={`url(#${maskId}-p${i})`}
                            />
                        ))}
                    {placed.map((g, i) => (
                        <path key={i} d={`M${g.x} 0${g.d}`} fill={ink} mask={`url(#${maskId}-${i})`} />
                    ))}
                </motion.svg>
            </div>
        </div>
    )
}

Signature.defaultProps = {
    text: "Ada Lovelace",
    ink: "#f5f5f4",
    size: BASE_SIZE,
    duration: 3,
    stagger: 0,
    delay: 0,
    outline: true,
    inset: 32,
    background: "transparent",
}

// Control order arranged in the builder.
